class Solution {
public:
    vector<vector<int>> getFactors(int n) {
        vector<vector<int>> res;
        vector<int> path;
        backtrack(2, n, path, res);
        return res;
    }

private:
    void backtrack(int start, int remain, vector<int>& path, vector<vector<int>>& res) {
        if (!path.empty()) {
            path.push_back(remain);
            res.push_back(path);
            path.pop_back();
        }
        for (int d = start; d * d <= remain; ++d) {
            if (remain % d == 0) {
                path.push_back(d);
                backtrack(d, remain / d, path, res);
                path.pop_back();
            }
        }
    }
};

class Solution {
    public List<List<Integer>> getFactors(int n) {
        List<List<Integer>> res = new ArrayList<>();
        backtrack(2, n, new ArrayList<>(), res);
        return res;
    }

    private void backtrack(int start, int remain, List<Integer> path, List<List<Integer>> res) {
        if (!path.isEmpty()) {
            List<Integer> combo = new ArrayList<>(path);
            combo.add(remain);
            res.add(combo);
        }
        for (int d = start; d * d <= remain; d++) {
            if (remain % d == 0) {
                path.add(d);
                backtrack(d, remain / d, path, res);
                path.remove(path.size() - 1);
            }
        }
    }
}

