var getFactors = function(n) {
    const res = [];
    function backtrack(start, remain, path) {
        if (path.length > 0) {
            res.push([...path, remain]);
        }
        for (let d = start; d * d <= remain; d++) {
            if (remain % d === 0) {
                path.push(d);
                backtrack(d, Math.floor(remain / d), path);
                path.pop();
            }
        }
    }
    backtrack(2, n, []);
    return res;
};
